CREATE TABLE migration_v70_maintenance_task_archive LIKE eam_maintenance_task;

INSERT INTO migration_v70_maintenance_task_archive SELECT * FROM eam_maintenance_task;

CREATE TABLE eam_maintenance_task_person (tenant_id BIGINT NOT NULL,task_id BIGINT NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,task_id,role_code,user_id),INDEX(tenant_id,user_id,role_code),FOREIGN KEY(task_id) REFERENCES eam_maintenance_task(id) ON DELETE CASCADE);

INSERT INTO eam_maintenance_task_person SELECT t.tenant_id,t.id,'owner',j.user_id,MIN(j.n) FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.snapshot,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j GROUP BY t.tenant_id,t.id,j.user_id;

INSERT INTO eam_maintenance_task_person SELECT t.tenant_id,t.id,'reviewer',j.user_id,MIN(j.n) FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.snapshot,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j GROUP BY t.tenant_id,t.id,j.user_id;

INSERT INTO eam_maintenance_task_person SELECT t.tenant_id,t.id,'collaborator',j.user_id,MIN(j.n) FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.collaborators'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j GROUP BY t.tenant_id,t.id,j.user_id;

CREATE TABLE eam_maintenance_execution (tenant_id BIGINT NOT NULL,task_id BIGINT NOT NULL,`description` TEXT NULL,`started_at` DATETIME(6) NULL,`work_start_at` DATETIME(6) NULL,`work_end_at` DATETIME(6) NULL,`review_decision` VARCHAR(24) NULL,`review_description` TEXT NULL,`acceptance_score` DECIMAL(8,2) NULL,PRIMARY KEY(tenant_id,task_id),FOREIGN KEY(task_id) REFERENCES eam_maintenance_task(id) ON DELETE CASCADE);

INSERT INTO eam_maintenance_execution SELECT tenant_id,id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.description')),'null'),''),CAST(REPLACE(NULLIF(COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.startedAt')),'null'),''),''),'T',' ') AS DATETIME(6)),CAST(REPLACE(NULLIF(COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.startAt')),'null'),''),''),'T',' ') AS DATETIME(6)),CAST(REPLACE(NULLIF(COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.endAt')),'null'),''),''),'T',' ') AS DATETIME(6)),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.acceptance.decision')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.acceptance.description')),'null'),''),CAST(NULLIF(COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(result,'$.acceptance.score')),'null'),''),'') AS DECIMAL(8,2)) FROM eam_maintenance_task WHERE result IS NOT NULL;

CREATE TABLE eam_maintenance_execution_item (tenant_id BIGINT NOT NULL,task_id BIGINT NOT NULL,item_key VARCHAR(255) NOT NULL,sort_no INT NOT NULL,result_value TEXT NOT NULL,abnormal TINYINT NOT NULL,resolved TINYINT NOT NULL,measure TEXT NOT NULL,remark TEXT NOT NULL,implicit_normal TINYINT NOT NULL,skipped TINYINT NOT NULL,PRIMARY KEY(tenant_id,task_id,item_key),FOREIGN KEY(tenant_id,task_id) REFERENCES eam_maintenance_execution(tenant_id,task_id) ON DELETE CASCADE);

INSERT INTO eam_maintenance_execution_item SELECT t.tenant_id,t.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'null'),''),j.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.value')),'null'),''),IF(JSON_EXTRACT(j.value,'$.abnormal') IN (CAST('true' AS JSON),1),1,0),IF(JSON_EXTRACT(j.value,'$.resolved') IN (CAST('true' AS JSON),1),1,0),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.measure')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.remark')),'null'),''),IF(JSON_EXTRACT(j.value,'$.implicitNormal') IN (CAST('true' AS JSON),1),1,0),IF(JSON_EXTRACT(j.value,'$.skipped') IN (CAST('true' AS JSON),1),1,0) FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j;

CREATE TABLE eam_maintenance_execution_image (tenant_id BIGINT NOT NULL,task_id BIGINT NOT NULL,item_key VARCHAR(255) NOT NULL,sort_no INT NOT NULL,file_id VARCHAR(64) NOT NULL,name_snapshot VARCHAR(255) NOT NULL,content_type VARCHAR(150) NOT NULL,size_bytes BIGINT NOT NULL,url_snapshot VARCHAR(1000) NOT NULL,PRIMARY KEY(tenant_id,task_id,item_key,sort_no),FOREIGN KEY(tenant_id,task_id,item_key) REFERENCES eam_maintenance_execution_item(tenant_id,task_id,item_key) ON DELETE CASCADE);

INSERT INTO eam_maintenance_execution_image SELECT t.tenant_id,t.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'null'),''),f.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.id')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.name')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.contentType')),'null'),''),COALESCE(JSON_EXTRACT(f.value,'$.size'),0),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.url')),'null'),'') FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.value,'$.images'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) f;

CREATE TABLE eam_maintenance_execution_file (tenant_id BIGINT NOT NULL,task_id BIGINT NOT NULL,stage_code VARCHAR(16) NOT NULL,sort_no INT NOT NULL,file_id VARCHAR(64) NOT NULL,name_snapshot VARCHAR(255) NOT NULL,content_type VARCHAR(150) NOT NULL,size_bytes BIGINT NOT NULL,url_snapshot VARCHAR(1000) NOT NULL,PRIMARY KEY(tenant_id,task_id,stage_code,sort_no),FOREIGN KEY(tenant_id,task_id) REFERENCES eam_maintenance_execution(tenant_id,task_id) ON DELETE CASCADE);

INSERT INTO eam_maintenance_execution_file SELECT t.tenant_id,t.id,'execution',f.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.id')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.name')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.contentType')),'null'),''),COALESCE(JSON_EXTRACT(f.value,'$.size'),0),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.url')),'null'),'') FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.attachments'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) f;

INSERT INTO eam_maintenance_execution_file SELECT t.tenant_id,t.id,'acceptance',f.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.id')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.name')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.contentType')),'null'),''),COALESCE(JSON_EXTRACT(f.value,'$.size'),0),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.url')),'null'),'') FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.acceptance.attachments'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) f;

CREATE VIEW v_maintenance_execution_item AS SELECT i.*,JSON_OBJECT('id',i.item_key,'value',i.result_value,'abnormal',IF(i.abnormal=1,CAST('true' AS JSON),CAST('false' AS JSON)),'resolved',IF(i.resolved=1,CAST('true' AS JSON),CAST('false' AS JSON)),'measure',i.measure,'remark',i.remark,'implicitNormal',IF(i.implicit_normal=1,CAST('true' AS JSON),CAST('false' AS JSON)),'skipped',IF(i.skipped=1,CAST('true' AS JSON),CAST('false' AS JSON)),'images',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_image r WHERE r.tenant_id=i.tenant_id AND r.task_id=i.task_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY())) item_view FROM eam_maintenance_execution_item i;

CREATE VIEW v_maintenance_task AS SELECT t.id,t.tenant_id,t.code,t.plan_id,t.equipment_id,t.company_id,t.department_id,t.owner_id,t.status,t.row_version,t.created_at,t.updated_at,t.type_id,t.schedule_id,t.due_date,t.expires_date,JSON_SET(t.snapshot,'$.owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'$.reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY())) snapshot,IF(e.task_id IS NULL,NULL,JSON_OBJECT('description',COALESCE(e.`description`,''),'startedAt',COALESCE(DATE_FORMAT(e.`started_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'startAt',COALESCE(DATE_FORMAT(e.`work_start_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'endAt',COALESCE(DATE_FORMAT(e.`work_end_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_maintenance_execution_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='execution' LIMIT 1),JSON_ARRAY()),'acceptance',JSON_OBJECT('decision',COALESCE(e.`review_decision`,''),'description',COALESCE(e.`review_description`,''),'score',e.`acceptance_score`,'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='acceptance' LIMIT 1),JSON_ARRAY())),'collaborators',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='collaborator' LIMIT 1),JSON_ARRAY()))) result FROM eam_maintenance_task t LEFT JOIN eam_maintenance_execution e ON e.tenant_id=t.tenant_id AND e.task_id=t.id;

UPDATE eam_maintenance_task SET snapshot=JSON_REMOVE(snapshot,'$.owners','$.reviewers');

ALTER TABLE eam_maintenance_task DROP COLUMN result;

