INSERT INTO eam_inspection_execution_image SELECT t.tenant_id,t.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'null'),''),f.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.id')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.name')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.contentType')),'null'),''),COALESCE(JSON_EXTRACT(f.value,'$.size'),0),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(f.value,'$.url')),'null'),'') FROM eam_inspection_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.value,'$.images'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) f;

