INSERT INTO eam_inspection_execution_review_item SELECT t.tenant_id,t.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'null'),''),j.n,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.decision')),'null'),''),COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.description')),'null'),'') FROM eam_inspection_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.result,'$.reviewItems'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j;

CREATE VIEW v_inspection_execution_item AS SELECT i.*,JSON_OBJECT('id',i.item_key,'value',i.result_value,'abnormal',IF(i.abnormal=1,CAST('true' AS JSON),CAST('false' AS JSON)),'resolved',IF(i.resolved=1,CAST('true' AS JSON),CAST('false' AS JSON)),'measure',i.measure,'remark',i.remark,'implicitNormal',IF(i.implicit_normal=1,CAST('true' AS JSON),CAST('false' AS JSON)),'skipped',IF(i.skipped=1,CAST('true' AS JSON),CAST('false' AS JSON)),'images',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_image r WHERE r.tenant_id=i.tenant_id AND r.task_id=i.task_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY())) item_view FROM eam_inspection_execution_item i;

CREATE VIEW v_inspection_task AS SELECT t.id,t.tenant_id,t.code,t.plan_id,t.equipment_id,t.company_id,t.department_id,t.owner_id,t.status,t.row_version,t.created_at,t.updated_at,t.type_id,t.kind,t.shift_id,t.due_at,t.expires_at,t.deleted,JSON_SET(t.snapshot,'$.owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'$.reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'$.personMode',t.person_mode) snapshot,IF(e.task_id IS NULL,NULL,JSON_OBJECT('description',COALESCE(e.`description`,''),'startedAt',COALESCE(DATE_FORMAT(e.`started_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'finishedAt',COALESCE(DATE_FORMAT(e.`finished_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'skipReason',COALESCE(e.`skip_reason`,''),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_execution_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='execution' LIMIT 1),JSON_ARRAY()),'review',JSON_OBJECT('decision',COALESCE(e.`review_decision`,''),'description',COALESCE(e.`review_description`,''),'reviewer',COALESCE(e.`reviewer_name`,''),'reviewedAt',COALESCE(DATE_FORMAT(e.`reviewed_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='review' LIMIT 1),JSON_ARRAY())),'scannedEquipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_equipment r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.action_code='scan' LIMIT 1),JSON_ARRAY()),'skippedEquipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_equipment r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.action_code='skip' LIMIT 1),JSON_ARRAY()),'reviewItems',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.item_key,'decision',r.decision,'description',r.description)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_review_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()))) result FROM eam_inspection_task t LEFT JOIN eam_inspection_execution e ON e.tenant_id=t.tenant_id AND e.task_id=t.id;

UPDATE eam_inspection_task SET snapshot=JSON_REMOVE(snapshot,'$.owners','$.reviewers','$.personMode');

ALTER TABLE eam_inspection_task DROP COLUMN result;
